import os
import time
import signal
import spidev
import gpiozero
import picamera2
import adafruit_circuitpython_mcp3002
import paho.mqtt.client as mqtt

class LoadCellReader:
    def __init__(self, spi_bus, spi_chipselect, max_speed_hz, bits_per_word):
        self.spi = spidev.SpiDev(spi_bus, spi_chipselect, max_speed_hz=max_speed_hz, bits_per_word=bits_per_word)
        self.spi.open()
        self.adc = adafruit_circuitpython_mcp3002.MCP3002(self.spi)

    def close(self):
        self.spi.close()

    def read_raw_data(self):
        raw_data = self.adc.read_raw()
        return raw_data

    def convert_to_weight(self, raw_data):
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def send_spi_command(self, spi, data):
        response = spi.xfer2(data)
        return response

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def main(self):
        try:
            self.close()
        except (OSError, IOError):
            print("SPI device not found or bus failed.")
        except Exception as e:
            print(f"An error occurred: {e}")

        try:
            mqtt_client = mqtt.Client()
            mqtt_client.connect("mqtt.example.com", 1883, 60)
            mqtt_client.subscribe("load_cell")

            while True:
                raw_data = self.read_raw_data()
                weight = self.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
                time.sleep(0.5)

                if mqtt_client.is_connected():
                    mqtt_client.publish("load_cell", weight)

        except KeyboardInterrupt:
            self.close()
            print("Shutting down...")
            os._exit(0)

        except Exception as e:
            print(f"An error occurred: {e}")
            os._exit(0)

        finally:
            mqtt_client.disconnect()
            self.close()
            print("Exiting...")

if __name__ == "__main__":
    try:
        load_cell_reader = LoadCellReader("/dev/spidev0.0", 0, 50000, 8)
        load_cell_reader.main()
    except KeyboardInterrupt:
        load_cell_reader.close()
        print("Shutting down...")
        os._exit(0)

