                    continue
                key, value = line.strip().split('=')
                if key == 'Sensor1_Type':
                    sensor_type = value
                elif key == 'Sensor1_Address':
                    sensor_address = int(value, 16)
                elif key == 'Sensor1_ID':
                    sensor_id = int(value, 16)
                elif key == 'Sensor2_Type':
                    sensor_type = value
                elif key == 'Sensor2_Address':
