                elif key == 'Sensor2_ID':
                    sensor_id = int(value, 16)
                elif key == 'Sensor3_Type':
                    sensor_type = value
                elif key == 'Sensor3_Address':
                    sensor_address = int(value, 16)
                elif key == 'Sensor3_ID':
                    sensor_id = int(value, 16)
                elif key == 'Sampling_Interval_Seconds':
                    interval = int(value)
                else:
                    raise ValueError(f"Invalid key: {key}")
        return sensor_type, sensor_address, sensor_id, interval
    except FileNotFoundError:
        print("Error: Config file not found.")
        return None

sensor_type, sensor_address, sensor_id, sampling_interval = load_config()

