                return

        # Validate MS8607
        if sensor_type == 'MS8607':
            if pressure is None or temperature is None:
                print("Warning: MS8607 readings are not available.")
                return

        # Store valid readings in SQLite database
        if pressure is not None and temperature is not None and humidity is not None:
            timestamp = datetime.now().isoformat()
            cursor.execute("INSERT INTO sensor_data (timestamp, pressure, temperature, humidity) VALUES (?, ?, ?, ?)",
                           (timestamp, pressure, temperature, humidity))
            conn.commit()

        # Log errors
        if pressure is None or temperature is None or humidity is None:
            print(f"Warning: Invalid sensor readings: {timestamp}")

    except Exception as e:
