class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path="."):
        self.display = display
        self.width = width
        self.height = height
        self.folder_path = folder_path
        self.is_running = False
        self.mqtt_client = MQTTClient()
        self.mqtt_client.connect("localhost", 1883, 60)
        self.mqtt_client.subscribe("animated_gif")

    def load_files(self):
        self.files = []
        for filename in os.listdir(self.folder_path):
            if filename.endswith(".gif"):
                self.files.append(filename)

    def preload(self):
        for file in self.files:
            img = Image.open(os.path.join(self.folder_path, file))
            if img.is_animated:
                duration = img.info.get('duration')
                loop = img.info.get('loop')
                if loop == 0:
                    loop = "inf"
                frame_width, frame_height = img.size
                frame_image = ImageOps.pad(img, (0, 0, frame_width - img.width, frame_height - img.height), "black", mode="nearest", fill="black")
                frame_image.save(os.path.join(self.folder_path, file))
        self.is_running = False

