import time
from gpiozero import GPIO, PWM

class FanControl:
    def __init__(self, fan_pin, temp_threshold_low, temp_threshold_high, pwm_duty_cycle_high, pwm_duty_cycle_low):
        self.fan_pin = fan_pin
        self.temp_threshold_low = temp_threshold_low
        self.temp_threshold_high = temp_threshold_high
        self.pwm_duty_cycle_high = pwm_duty_cycle_high
        self.pwm_duty_cycle_low = pwm_duty_cycle_low
        self.pwm = PWM(self.fan_pin, frequency=100)
        self.pwm.start(duty_cycle=self.pwm_duty_cycle_high)

    def stop_fan(self):
        self.pwm.stop()

    def set_duty_cycle(self, duty_cycle):
        if duty_cycle < self.pwm_duty_cycle_low or duty_cycle > self.pwm_duty_cycle_high:
            raise ValueError("Invalid duty cycle value")
        self.pwm.duty_cycle = duty_cycle

    def measure_temperature(self):
        try:
            output = subprocess.check_output(['vcgencmd', 'measure_temp']).decode('utf-8')
            temperature = float(output.split('=')[1].strip())
            return temperature
        except subprocess.CalledProcessError:
            print("Error: Failed to execute vcgencmd measure_temp")
            return None

    def update_duty_cycle(self):
        temperature = self.measure_temperature()
        if temperature is not None:
            duty_cycle = min(self.pwm_duty_cycle_high, max(self.pwm_duty_cycle_low, temperature * 0.9))
            self.set_duty_cycle(duty_cycle)
        else:
            self.set_duty_cycle(self.pwm_duty_cycle_high)

    def on_exit(self, signum, frame):
        self.stop_fan()
        GPIO.cleanup()

fan_control = FanControl(14, 70, 60, 100, 85)

try:
    while True:
        fan_control.update_duty_cycle()
        time.sleep(5)
except KeyboardInterrupt:
    fan_control.stop_fan()
    print("Exiting due to keyboard interrupt")
except Exception as e:
    fan_control.stop_fan()
    print(f"Error: {e}")

