        current_power = ina219_power_supply.current_power
        power_power = voltage_power_power * current_power

        print("Voltage Power: ", round(power_power, 2), "mW")
        print("Current Power: ", round(current_power, 2), "mW")
        print("Total Power: ", round(power_power, 2), "mW")

    except adafruit_ina219.INA219Error as e:
        print("Error reading INA219 sensor: ", e)

# Function to read all registers from UPS controller
def read_all_registers():
    try:
        registers = ups_object.read_all_registers()
        for register in registers:
            print(hex(register), hex(register >> 8), hex(register >> 16), hex(register >> 24))

    except adafruit_pigpio.PigpioError as e:
        print("Error reading UPS controller registers: ", e)

# Function to handle sensor absence
