    try:
        if ina219_power_supply.is_present:
            print("Sensor is present")
        else:
            print("Sensor is absent")

    except adafruit_ina219.INA219Error as e:
        print("Error handling sensor absence: ", e)

# Function to handle bus error
def handle_bus_error():
    try:
        if i2c.is_connected:
