import os
import signal
import sys
import time
from flask import Flask, render_template, request, redirect, url_for, session
from gpiozero import LED, Button
from paho.mqtt import client as mqtt
from paho.mqtt.server import MQTTServer

app = Flask(__name__)

# Module-level LED instance
led = LED(17)
button = Button(18)

# MQTT server setup
mqtt_server = MQTTServer(host='localhost', port=1883, keepalive=60)

# MQTT client setup
mqtt_client = mqtt.Client()
mqtt_client.connect("localhost", 1883, 60)

# MQTT topic for LED control
mqtt_topic = "led"

# MQTT message handler
def on_message(client, userdata, message):
    led.on()
    print(f"Received message: {message.payload.decode()}")

def on_disconnect(client):
    print("Disconnected from MQTT broker")

def handle_mqtt_message(topic, message):
    if topic == mqtt_topic:
        led.on()
        mqtt_client.publish(mqtt_topic, "ON")
        print("LED turned on")
    else:
        print(f"Received message on incorrect topic: {topic}")

# GPIO initialization error handling
def handle_gpio_error(error):
    print(f"Error initializing GPIO: {error}")

# Flask routes
@app.route('/')
def index():
    return render_template('index.html')

@app.route('/light_on')
def light_on():
    try:
        led.on()
        return redirect(url_for('index'))
    except Exception as e:
        handle_gpio_error(e)

@app.route('/light_off')
def light_off():
    try:
        led.off()
        return redirect(url_for('index'))
    except Exception as e:
        handle_gpio_error(e)

# Signal handling for program termination
def signal_handler(signal, frame):
    print("Shutting down the application")
    mqtt_server.stop()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    try:
        mqtt_server.start()
        mqtt_client.connect("localhost", 1883, 60)
        mqtt_server.loop_start()

        @app.route('/')
        def index():
            return render_template('index.html')

        @app.route('/light_on')
        def light_on():
            try:
                led.on()
                return redirect(url_for('index'))
            except Exception as e:
                handle_gpio_error(e)

        @app.route('/light_off')
        def light_off():
            try:
                led.off()
                return redirect(url_for('index'))
            except Exception as e:
                handle_gpio_error(e)

        @app.route('/mqtt_message', methods=['POST'])
        def handle_mqtt_message():
            topic = request.form['topic']
            message = request.form['message']
            handle_mqtt_message(topic, message)
            return "Message received and processed"

        app.run(host='0.0.0.0', port=8080, debug=False)
    except Exception as e:
