                try:
                    event = self.sensor_pin.wait_for_event(timeout=self.poll_interval)
                    if event:
                        self.last_events.append(datetime.now())
                except Exception as e:
                    logging.error(f"Error occurred while polling: {e}")
                    break
            time.sleep(self.poll_interval)

    def stop_poll(self):
        self.sensor_pin.clear()

    def start_mqtt_client(self, mqtt_broker, mqtt_topic):
        self.mqtt_client = MQTTClient(client_id="clean_energy_monitor", mqtt_broker=mqtt_broker)
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message
        self.mqtt_client.connect(mqtt_broker, 1883, 60)
        self.mqtt_client.loop_start()

    def on_connect(self, client, userdata, flags, rc):
        logging.info(f"Connected to MQTT broker with result code {rc}")

    def on_message(self, client, userdata, message):
        logging.info(f"Received message: {message.payload.decode('utf-8')}")

    def debounce(self, func, threshold):
        def wrapper(*args, **kwargs):
            nonlocal last_events
            last_events = []
            while True:
                try:
                    result = func(*args, **kwargs)
                    if result and result not in last_events:
                        last_events.append(result)
                except Exception as e:
                    logging.error(f"Error occurred while debouncing: {e}")
                    break
        return wrapper

    def run(self):
        self.start_poll()
        self.start_mqtt_client("localhost", "energy_monitoring")

        # Signal handling for graceful shutdown
        signal.signal(signal.SIGINT, self.on_sigint)
        signal.signal(signal.SIGTERM, self.on_sigterm)

        try:
            while True:
                time.sleep(1)
