class LEDController:
    def __init__(self, pin):
        try:
            self.led = LED(pin)
            self.button = Button(18)
            self.mqtt_client = MQTTClient("mqtt.example.com", 1883, 18)
        except ValueError as e:
            print(f"Invalid pin: {e}")
        except Exception as e:
            print(f"An error occurred during initialization: {e}")

    def on(self):
        self.led.on()
        print("LED turned on")

    def off(self):
        self.led.off()
        print("LED turned off")

    def blink(self, on_duration, off_duration):
        if on_duration >= 0 and off_duration >= 0:
            self.led.on()
            time.sleep(on_duration)
            self.led.off()
            time.sleep(off_duration)
        else:
            print("Invalid duration. Durations must be non-negative.")

    def run_blink(self):
        while True:
            try:
                self.blink(1.0, 0.5)
            except KeyboardInterrupt:
                self.off()
                print("LED turned off due to Ctrl+C or termination.")
            except Exception as e:
                print(f"An error occurred: {e}")

def main():
    try:
        led_controller = LEDController(22)
        led_controller.run_blink()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()

