            mqtt.connect("mqtt.example.com", 1883, 60)

            # Subscribe to pump status topic
            mqtt.subscribe("pump_status")

            # Define callback function for pump status updates
            def on_message(client, userdata, message):
                if message.payload == "on":
                    print("Pump turned on")
                elif message.payload == "off":
                    print("Pump turned off")

            # Set up MQTT callback
            mqtt.on_message = on_message

            # Start MQTT loop
            mqtt.loop_forever()

        # Initialize soil moisture sensor
        if soil_moisture_sensor:
            # Continuously read and print the soil moisture value
            while True:
                try:
                    soil_moisture_reading = soil_moisture_sensor.value
                    print(f"Soil moisture: {soil_moisture_reading}")
                except Exception as e:
                    print(f"Error reading soil moisture: {e}")
                time.sleep(1)

        # Continuously simulate soil moisture and turn the pump on/off
        while True:
            try:
                simulate_soil_moisture()
            except KeyboardInterrupt:
                # Graceful shutdown on KeyboardInterrupt
                print("Shutting down...")
                gpio.value = False
                time.sleep(1)
                # Release GPIO resources
                gpio.close()
                if mqtt:
                    mqtt.loop_stop()
                if soil_moisture_sensor:
                    soil_moisture_sensor.close()
                if water_pump:
                    water_pump.close()
                print("Exiting...")

if __name__ == "__main__":
    main()

