class I2CDevice:
    def __init__(self, address=0x1F, bus_number=1):
        self.bus_number = bus_number
        self.address = address
        self.bus = smbus2.SMBus(bus_number)
        self.device = smbus2.SMBus(bus_number)

        # Perform a quick I2C address probe
        try:
            self.device.write(self.address, b'\x00')
            self.device.write(self.address, b'\x01')
        except OSError:
            raise RuntimeError("Device does not acknowledge the I2C address probe")

    def write_byte(self, register, value):
        try:
            self.bus.write_byte(self.address, register, value)
        except OSError:
            raise RuntimeError("Error writing to the device")

    def read_byte(self, register):
        try:
            return self.bus.read_byte(self.address, register)
        except OSError:
            raise RuntimeError("Error reading from the device")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

