import time
import signal
import os
import paho.mqtt.client as mqtt
import gpiozero
import picamera2
import adafruit_circuitpython_serial as serial

class ESP8266Communicator:
    def __init__(self, tx_pin, rx_pin, baud_rate=115200):
        self.tx_pin = gpiozero.Pin(tx_pin)
        self.rx_pin = gpiozero.Pin(rx_pin)
        self.baud_rate = baud_rate
        self.serial_port = serial.Serial(
            port='/dev/ttyUSB0',
            baudrate=self.baud_rate,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            bytesize=serial.EIGHTBITS,
            timeout=5
        )

        self.signal_received = signal.signal(signal.SIGALRM, self.signal_handler)
        signal.alarm(5)

    def signal_handler(self, signum, frame):
        self.serial_port.close()
        self.tx_pin.off()
        self.rx_pin.off()
        raise SystemExit

    def _send_command(self, command, delay=1, max_retries=3):
        try:
            self.serial_port.write(command.encode())
            time.sleep(delay)
            response = self.serial_port.readline().decode()
            if response.startswith('OK'):
                return response
            elif response.startswith('ERROR'):
                return 'ERROR'
            elif response.startswith('FAIL'):
                return 'FAIL'
            else:
                return None
        except Exception as e:
            if max_retries > 0:
                return self._send_command(command, delay, max_retries - 1)
            else:
                raise e

    def _read_response(self):
        try:
            response = self.serial_port.readline().decode()
            if response.startswith('OK'):
                return response
            elif response.startswith('ERROR'):
                return 'ERROR'
            elif response.startswith('FAIL'):
                return 'FAIL'
            else:
                return None
        except Exception as e:
            return None

    def test_connection(self):
        command = 'AT\r\n'
        response = self._send_command(command)
        if response:
            if 'WIFI GOT IP' in response:
                return True
            else:
                return False
        else:
            return False

    def restart(self):
        command = 'AT+RST\r\n'
        self._send_command(command)
        time.sleep(2)
        response = self._read_response()
        if response:
            if 'OK' in response:
                return True
            else:
                return False
        else:
            return False

    def connect_wifi(self, ssid, password):
        command = 'AT+CWJAP_CUR="%s","%s"\r\n' % (ssid, password)
        self._send_command(command)
        response = self._read_response()
        if 'OK' in response:
            return True
        else:
            return False

