from flask import Flask, jsonify, request
import serial
import time
import threading
from gpiozero import Button
from picamera2 import PiCamera
from adafruit_circuitpython_serial import Serial
from paho.mqtt import client as mqtt_client

app = Flask(__name__)

# Global variables
serial_port = None
serial_thread = None
camera = PiCamera()

# MQTT configuration
mqtt_broker = "localhost"
mqtt_port = 1883
mqtt_topic = "pi/data"

# Serial port configuration
serial_baudrate = 9600
serial_port_name = "/dev/ttyUSB0"

# Item data store
item_data = []

# MQTT client
mqtt_client.connect(mqtt_broker, mqtt_port)

# Button to trigger data retrieval
button = Button(pin=22, pull=Pull.UP)

# Routes
@app.route('/version')
def version():
    global serial_port
    try:
        serial_port = serial.Serial(serial_port_name, serial_baudrate, timeout=0.1)
        return jsonify({"status": "success"}), 200
    except serial.SerialException as e:
        return jsonify({"status": "error", "message": str(e)}), 503
    finally:
        if serial_port:
            serial_port.close()

@app.route('/getdata')
def get_data():
    global item_data
    try:
        serial_port = serial.Serial(serial_port_name, serial_baudrate, timeout=0.1)
        item_data = [item.strip() for item in serial_port.readlines().decode().split('\n') if item.strip()]
        serial_port.close()
        return jsonify(item_data), 200
    except serial.SerialException as e:
        return jsonify({"status": "error", "message": str(e)}), 503
    finally:
        if serial_port:
            serial_port.close()

@app.route('/getset/<int:item_id>', methods=['POST'])
def get_set(item_id):
    global item_data
    try:
        item_data[item_id - 1] = request.form.get('value')
        serial_port = serial.Serial(serial_port_name, serial_baudrate, timeout=0.1)
        serial_port.write(bytes(item_data[item_id - 1], 'utf-8'))
        serial_port.close()
        return jsonify({"status": "success"}), 200
    except serial.SerialException as e:
        return jsonify({"status": "error", "message": str(e)}), 503
    finally:
        if serial_port:
            serial_port.close()

@app.route('/postjson', methods=['POST'])
def post_json():
    global item_data
    try:
        if request.headers.get('Content-Type') == 'application/json':
            data = request.get_json()
            item_id = data.get('id')
            item_name = data.get('name', '')
            done = data.get('done', False)
            if item_id and item_name and done:
                item_data.append({
                    'id': item_id,
                    'name': item_name,
                    'done': done
                })
                serial_port = serial.Serial(serial_port_name, serial_baudrate, timeout=0.1)
                serial_port.write(bytes(str(len(item_data)) + '\n', 'utf-8'))
                serial_port.close()
                return jsonify(item_data), 200
            else:
                return jsonify({"status": "error", "message": "Invalid input"}), 400
        else:
            return jsonify({"status": "error", "message": "Invalid content type"}), 400
    except serial.SerialException as e:
        return jsonify({"status": "error", "message": str(e)}), 503
    finally:
        if serial_port:
            serial_port.close()

